<script setup lang="ts">const props=defineProps<{caseId:string}>();const emit=defineEmits<{decide:[caseId:string,decision:"approve"|"needs_changes"|"reject",reasonCode:string,note:string]}>();const decision=ref<"approve"|"needs_changes"|"reject">("approve"),reasonCode=ref("FALSE_POSITIVE"),note=ref("");function submit(){emit("decide",props.caseId,decision.value,reasonCode.value,note.value);note.value="";}</script>
<template><form class="moderation-decision-form" @submit.prevent="submit"><h3>تصمیم بازبین</h3><label>نتیجه<select v-model="decision"><option value="approve">تأیید انتشار</option><option value="needs_changes">نیازمند اصلاح</option><option value="reject">رد آگهی</option></select></label><label>کد دلیل<select v-model="reasonCode"><option value="FALSE_POSITIVE">مثبت کاذب</option><option value="DUPLICATE_CONFIRMED">تکراری تأیید شد</option><option value="POLICY_VIOLATION">نقض سیاست</option><option value="CONTACT_IN_TEXT">اطلاعات تماس در متن</option></select></label><label>یادداشت ممیزی<textarea v-model="note" maxlength="1000" rows="4" placeholder="دلیل قابل فهم برای کاربر و ممیزی"></textarea></label><button class="button button-primary">ثبت تصمیم</button></form></template>
